/* Flat / Metro — saturated solids, zero shadow, sharp geometry, big type */
.theme-flat {
  --bg: oklch(0.96 0.004 250);
  --surface: oklch(1 0 0);
  --surface-2: oklch(0.9 0.035 250);
  --fg: oklch(0.2 0.01 250);
  --fg-muted: oklch(0.5 0.012 250);
  --accent: oklch(0.6 0.19 30);
  --accent-fg: oklch(1 0 0);
  --accent-2: oklch(0.65 0.17 165);
  --line: oklch(0.86 0.008 250);
  --success: oklch(0.68 0.18 150);
  --warning: oklch(0.78 0.17 80);
  --danger: oklch(0.58 0.22 25);

  --radius: 0rem;
  --radius-sm: 0rem;
  --radius-lg: 0rem;
  --radius-pill: 0rem;

  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
  --glow: 0 0 0 3px var(--accent);

  --border-width: 0px;
  --blur-amount: 0px;

  --font-display: "Titillium Web", "Segoe UI", sans-serif;
  --font-body: "Titillium Web", "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.035em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-flat h1,
.theme-flat h2,
.theme-flat h3 {
  font-family: var(--font-display);
  font-weight: 300;
  letter-spacing: var(--tracking-display);
}

.theme-flat h1 {
  font-weight: 200;
}

/* signature */
.theme-flat { --font-ui: var(--font-display); }
.theme-flat h1 { font-weight: 900; text-transform: uppercase; letter-spacing: -0.01em; }
.theme-flat h2 { color: var(--accent); font-weight: 700; }
.theme-flat button { transition: none; }

/* depth */
.theme-flat thead th { background: var(--surface-2); text-transform: uppercase; letter-spacing: var(--label-tracking); font-size: 0.72em; font-weight: 600; text-align: left; border: 0; }
.theme-flat td { border-bottom: 1px solid var(--line); }
.theme-flat tbody tr:hover { background: var(--surface-2); }
.theme-flat input, .theme-flat select, .theme-flat textarea { border: 2px solid var(--line); border-radius: 0; background: var(--surface); transition: none; }
.theme-flat input:focus, .theme-flat select:focus, .theme-flat textarea:focus { outline: none; border-color: var(--accent); box-shadow: none; }
/* physical: links behave like Metro tiles — hover fills solid, no underline */
.theme-flat a { text-decoration: none; color: var(--accent); }
.theme-flat a:hover { background: var(--accent); color: var(--accent-fg); text-decoration: none; }
.theme-flat button:active { transform: scale(0.97); transition: none; }
.theme-flat kbd { font-family: var(--font-mono); font-size: 0.85em; padding: 0.1em 0.45em; background: var(--surface-2); border: 0; border-radius: 0; }
.theme-flat ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-flat ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-flat ::-webkit-scrollbar-track { background: var(--bg); }
.theme-flat ::-webkit-scrollbar-thumb { background: var(--fg-muted); border-radius: 0; }
.theme-flat ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-flat .label-caps { color: var(--accent-2); font-weight: 600; }
.theme-flat .themed-border { border-left: 6px solid var(--accent); }

/* alt mode: dark tiles — saturated solids read even louder on charcoal */
.theme-flat.alt-mode {
  --bg: oklch(0.145 0.004 250.0);
  --surface: oklch(0.185 0.004 250.0);
  --surface-2: oklch(0.225 0.004 250.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 16%);
  --accent: oklch(0.66 0.19 30);
  --accent-2: oklch(0.72 0.17 165);
  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
}
.theme-flat.alt-mode a { color: oklch(0.72 0.17 30); }
.theme-flat.alt-mode a:hover { background: var(--accent); color: var(--accent-fg); }
.theme-flat.alt-mode ::-webkit-scrollbar-track { background: var(--bg); }
.theme-flat.alt-mode .label-caps { color: var(--accent-2); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
